import json, sys
from datetime import datetime, timezone


def parse_aware(s):
    """Parse an offset-aware ISO8601 string into an aware UTC datetime.

    Returns None for missing, non-string, naive, or unparseable values so
    that callers can skip them per the contract.
    """
    if not isinstance(s, str):
        return None
    try:
        dt = datetime.fromisoformat(s)
    except ValueError:
        return None
    if dt.tzinfo is None:
        return None  # naive -> skip
    return dt.astimezone(timezone.utc)


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_aware(data.get("as_of"))
    reminders = data.get("reminders") or []

    # Keep the parsed instant for sorting, then drop it from output.
    results = []
    for r in reminders:
        if r.get("completed"):
            continue
        dt = parse_aware(r.get("due"))
        if dt is None:
            continue  # missing / null / naive / invalid due
        if as_of is not None and dt <= as_of:
            results.append((dt, str(r["id"]), r.get("title")))

    # Sort by actual due instant, then by id.
    results.sort(key=lambda t: (t[0], t[1]))

    out = [
        {
            "id": i,
            "title": t,
            "due_utc": dt.strftime("%Y-%m-%dT%H:%M:%SZ"),
        }
        for dt, i, t in results
    ]
    print(json.dumps(out))


if __name__ == "__main__":
    main()
